	@Test
	void copyPreservesOnlyActualMappingsAndKeepsPresentNullDistinctFromUndef() {
		ListBindingSet undefInput = new ListBindingSet(List.of("bound", "undefined"), REQUEST, null);
		QueryBindingSet copiedUndef = (QueryBindingSet) context.createBindingSet(undefInput);
		assertAll(
				() -> assertSame(REQUEST, copiedUndef.getValue("bound")),
				() -> assertTrue(copiedUndef.hasBinding("bound")),
				() -> assertFalse(copiedUndef.hasBinding("undefined"),
						"schema-only UNDEF is not an actual copied mapping"),
				() -> assertFalse(copiedUndef.getBindingNames().contains("undefined")));

		QueryBindingSet presentNull = new QueryBindingSet();
		presentNull.setBinding("presentNull", null);
		QueryBindingSet copiedNull = (QueryBindingSet) context.createBindingSet(presentNull);
		assertTrue(presentNull.hasBinding("presentNull"));
		assertTrue(copiedNull.hasBinding("presentNull"), "a real present-null mapping remains present");
		assertNull(copiedNull.getValue("presentNull"));

		QueryBindingSet absent = (QueryBindingSet) context.createBindingSet(new QueryBindingSet());
		assertFalse(absent.hasBinding("absent"));
		assertFalse(absent.getBindingNames().contains("absent"));
	}

	@Test
	void copyPreservesGraphAndBindingSetOriginMetadata() {
		MapBindingSet requestInput = new MapBindingSet();
		requestInput.addBinding("request", REQUEST);
		QueryBindingSet source = new QueryBindingSet(BindingSetOrigin.requestInput(requestInput));
		source.addBinding("local", LOCAL);
		BindingSetOrigin.set(source, BindingSetOrigin.of(source).producing(Set.of("local")));
		GraphFrameBindings.supply(source, "privateGraph", GRAPH);

		QueryBindingSet copied = (QueryBindingSet) context.createBindingSet(source);
		assertAll(
				() -> assertSame(REQUEST, copied.getValue("request")),
				() -> assertSame(LOCAL, copied.getValue("local")),
				() -> assertSame(GRAPH, copied.getValue("privateGraph")),
				() -> assertTrue(BindingSetOrigin.of(copied).isRequest("request"), "request provenance survives copy"),
				() -> assertTrue(BindingSetOrigin.of(copied).isLocal("local"), "local provenance survives copy"),
				() -> assertTrue(GraphFrameBindings.isSupplied(copied, "privateGraph")));
		copied.setBinding("copyOnly", REQUEST);
		assertFalse(source.hasBinding("copyOnly"), "copy owns its mapping");
	}

	@Test
	void copyRetainsDormantRequestParameterAuthorityWithoutCreatingAMapping() {
		MapBindingSet supplied = new MapBindingSet();
		supplied.addBinding("parameter", REQUEST);
		BindingSet hidden = BindingSetOrigin.optimizationInput(supplied);
		assertFalse(hidden.hasBinding("parameter"));
		assertSame(REQUEST, BindingSetOrigin.of(hidden).parameterValue("parameter"));

		QueryBindingSet copied = (QueryBindingSet) context.createBindingSet(hidden);
		assertAll(
				() -> assertFalse(copied.hasBinding("parameter"),
						"hidden request values stay outside the solution mapping"),
				() -> assertTrue(BindingSetOrigin.isTrackedInput(copied)),
				() -> assertTrue(BindingSetOrigin.of(copied).isRequest("parameter")),
				() -> assertSame(REQUEST, BindingSetOrigin.of(copied).parameterValue("parameter")));
	}

	@Test
	void copyUsesVisibleGraphFrameFromCustomCarrierIncludingAnEmptyMask() {
		MapBindingSet requestInput = new MapBindingSet();
		requestInput.addBinding("request", REQUEST);
		QueryBindingSet delegate = new QueryBindingSet(BindingSetOrigin.requestInput(requestInput));
		GraphFrameBindings.supply(delegate, "privateGraph", GRAPH);
		TestBindingCarrier masked = new TestBindingCarrier(delegate, GraphFrameBindings.EMPTY,
				BindingSetOrigin.of(delegate), true);
		assertSame(GRAPH, masked.getValue("privateGraph"));
		assertFalse(GraphFrameBindings.isSupplied(masked, "privateGraph"),
				"an explicit empty carrier mask hides the delegate's stale graph authority");

		QueryBindingSet copied = (QueryBindingSet) context.createBindingSet(masked);
		assertAll(
				() -> assertSame(REQUEST, copied.getValue("request")),
				() -> assertSame(GRAPH, copied.getValue("privateGraph")),
				() -> assertFalse(GraphFrameBindings.isSupplied(copied, "privateGraph")),
				() -> assertTrue(BindingSetOrigin.isTrackedInput(copied)),
				() -> assertTrue(BindingSetOrigin.of(copied).isRequest("request")));
	}

	@Test
	void copyOwnsAnIndependentMutableMapping() {
		QueryBindingSet source = new QueryBindingSet();
		source.setBinding("source", REQUEST);
		QueryBindingSet copied = (QueryBindingSet) context.createBindingSet(source);
		assertNotSame(source, copied);
		copied.setBinding("copyOnly", LOCAL);
		assertFalse(source.hasBinding("copyOnly"));
		assertSame(LOCAL, copied.getValue("copyOnly"));
	}

	@Test
	void inheritedGraphProjectionUsesTheContextCopyWithoutMaterializingAnUndefHeader() {
		ListBindingSet input = new ListBindingSet(List.of("callerGraph", "undefined"), GRAPH, null);
		BindingSet request = BindingSetOrigin.requestInput(input);
		assertTrue(BindingSetOrigin.of(request).isRequest("callerGraph"));
		assertFalse(BindingSetOrigin.of(request).isRequest("undefined"),
				"a schema-only header is not query-entry request authority");
		Projection projection = new Projection(new SingletonSet(),
				new ProjectionElemList(new ProjectionElem("callerGraph")));
		projection.setProjectionContext(Var.of("callerGraph"));
		projection.setInheritedGraphParameter("privateGraph");
		AtomicReference<BindingSet> childInput = new AtomicReference<>();
		QueryEvaluationStep child = bindings -> {
			childInput.set(bindings);
			return new CloseableIteratorIteration<>(List.of(bindings).iterator());
		};
		ProjectionQueryEvaluationStep step = new ProjectionQueryEvaluationStep(projection, child, context);
		try (CloseableIteration<BindingSet> rows = step.evaluate(request)) {
			assertTrue(rows.hasNext());
			rows.next();
		}

		BindingSet scoped = childInput.get();
		assertSame(GRAPH, scoped.getValue("callerGraph"));
		assertSame(GRAPH, scoped.getValue("privateGraph"));
		assertFalse(scoped.hasBinding("undefined"),
				"the real projection's inherited-graph lowering must not turn an UNDEF header into a present-null mapping");
		assertTrue(BindingSetOrigin.of(scoped).isRequest("callerGraph"),
				"the prepared projection copy retains its request-entry provenance");
		assertTrue(GraphFrameBindings.isSupplied(scoped, "privateGraph"));
	}

